// Manually implemented — not generated by codegen.
// CZ_SETTING_WHISPER_STATE (0x00CF) has no C struct in rAthena; it is a
// fixed-size parseable_packet(0x00cf, 27, clif_parse_PMIgnore, 2, 26).
//
// Wire format: uint16 packetType | char nick[24] | uint8 type
// pos[0]=2 (nick at offset 2), pos[1]=26 (type at offset 26). Total: 27 bytes.

package encode

import (
	"github.com/lenaxia/rathena-client/pkg/send"
)

// EncodeSetWhisperState encodes a SetWhisperState packet (CZ_SETTING_WHISPER_STATE / 0x00CF).
// Returns a fixed 27-byte array.
func EncodeSetWhisperState(req send.SetWhisperState, _ uint32) [27]byte {
	const nameLen = 24
	var p [27]byte
	// Packet ID: 0x00CF (little-endian)
	p[0] = 0xcf
	p[1] = 0x00
	// nick[24] at offset 2, NUL-padded by zero-value array
	copy(p[2:2+nameLen], req.Nick)
	// type at offset 26
	p[26] = req.Type
	return p
}
